# Dynamic batching pseudocode (简化版)
wait_time = 50  # ms
min_batch, max_batch = 8, 16

while True:
    batch = []
    deadline = time.time() + wait_time / 1000
    while len(batch) < max_batch and time.time() < deadline:
        try:
            req = queue.get(timeout=deadline - time.time())
            batch.append(req)
        except Empty:
            break
    if len(batch) >= min_batch or batch:
        results = model.batched_inference(batch)  # FP16 + cached features
        for req, result in zip(batch, results):
            req.callback(result)
